+            auto* padSynth = audioEngine_->getPadSynth(p);
+            if (padSynth && padSynth->isActive()) {
+sum += padSynth->process();
+active++;
+            }
+        }
+    }
     activeVoiceCount_.store(active, std::memory_order_relaxed);
     return sum * masterVolume_;
 }

