sealed class KeyboardTarget(val displayName: String) {
    object Synth : KeyboardTarget("Synth")
    object SamplerA : KeyboardTarget("Smp A")
    object SamplerB : KeyboardTarget("Smp B")
    data class Track(val index: Int) : KeyboardTarget("Tr${index + 1}")
}

